#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# fastbox window harness (adapted from G013 ab_window.sh). Syncs a fixed block window from a snapshot, per arm and round.
# usage: fb_window.sh <outdir> <END height> <TIMEOUT s> <ROUNDS> "<label>|<monerod>|<extra args>" ["<label>|..."]
# Required env: PEER (host:port, exclusive P2P peer), PEER_RPC (host:port, peer RPC for the hash check),
#   DD (scratch data dir owned by the kit), SNAP (dir holding testnet/lmdb/data.mdb).
# Optional env: P2P_PORT (38080), RPC_PORT (38081); test-only: IDLE_S (45), SETTLE_S (3).
# The peer may be a local node (PEER=127.0.0.1:28080): its CPU over the window is read from /proc (read-only) into peer_cpu_s.
# No internet: P2P bound to 127.0.0.1, one exclusive peer, no IGD, no ZMQ, no DNS checkpoints, no update checks.
# Safety: only PIDs this script started are signalled. Before every run it refuses if our ports are taken. DD is
# deleted only if it holds the marker file .fastbox_scratch that this script created.
# Output: <outdir>/results.csv plus per-run logs. Completion marker: last line of <outdir>/summary.txt is AB_COMPLETE.
set -u
[ $# -ge 5 ] || { echo "usage: fb_window.sh <outdir> <END> <TIMEOUT s> <ROUNDS> \"label|binary|extra\"..." >&2; exit 2; }
OUT=$1; END=$2; TO=$3; ROUNDS=$4; shift 4
ARMS=("$@")
for v in PEER PEER_RPC DD SNAP; do [ -n "${!v:-}" ] || { echo "fb_window: env $v is required" >&2; exit 2; }; done
P2P_PORT=${P2P_PORT:-38080}; RPC_PORT=${RPC_PORT:-38081}
IDLE_S=${IDLE_S:-45}; SETTLE_S=${SETTLE_S:-3}
PEER_HOST=${PEER%:*}
[ -f "$SNAP/testnet/lmdb/data.mdb" ] || { echo "fb_window: no $SNAP/testnet/lmdb/data.mdb" >&2; exit 2; }
mkdir -p "$OUT"
S=$OUT/summary.txt; R=$OUT/results.csv
echo "fb_window start $(date -Is) end=$END timeout=$TO rounds=$ROUNDS arms=${#ARMS[@]}" > "$S"
for a in "${ARMS[@]}"; do IFS='|' read -r l b x <<< "$a"; echo "arm $l: $b $x | $(sha256sum "$b" | cut -c1-16)" >> "$S"; done
echo "snap $SNAP dd $DD ports p2p=$P2P_PORT rpc=$RPC_PORT" >> "$S"
echo "round,arm,start_h,end_h,blocks,wall_s,peak_anon_MB,peak_privdirty_MB,peak_rss_MB,read_MB,write_MB,tip_height,hash_match,post_idle_anon_MB,cpu_s,peer_cpu_s" > "$R"

CUR_PID=
cleanup() { [ -n "$CUR_PID" ] && kill -TERM "$CUR_PID" 2>/dev/null; }  # only the PID we started
trap cleanup EXIT
trap 'exit 130' INT TERM

refuse() { echo "REFUSE: $*" >> "$S"; echo "fb_window: REFUSE: $*" >&2; exit 3; }
port_busy() { ss -ltn 2>/dev/null | awk 'NR>1{print $4}' | grep -qE "[:.]$1\$"; }
check_ports() { for p in "$P2P_PORT" "$RPC_PORT"; do port_busy "$p" && refuse "port $p already has a listener"; done; }

prep_dd() {  # <tag>
  case "$DD" in /|"$HOME"|"$HOME"/) refuse "DD=$DD is not a scratch dir";; esac
  if [ -e "$DD" ] && [ -n "$(ls -A "$DD" 2>/dev/null)" ] && [ ! -f "$DD/.fastbox_scratch" ]; then
    refuse "DD=$DD is not empty and has no .fastbox_scratch marker"
  fi
  rm -rf "$DD"
  mkdir -p "$DD/testnet/lmdb" || refuse "cannot create $DD"
  touch "$DD/.fastbox_scratch"
  local t0 t1 a b
  t0=$(date +%s.%N)
  cp -- "$SNAP/testnet/lmdb/data.mdb" "$DD/testnet/lmdb/data.mdb" || refuse "copy of snapshot failed"
  t1=$(date +%s.%N)
  a=$(stat -c %s "$SNAP/testnet/lmdb/data.mdb"); b=$(stat -c %s "$DD/testnet/lmdb/data.mdb")
  [ "$a" = "$b" ] || refuse "copied data.mdb is $b bytes, snapshot is $a"
  echo "[$1] copied snapshot: $b bytes (size matches) in $(awk -v a="$t0" -v b="$t1" 'BEGIN{printf "%.1f", b-a}') s" >> "$S"
}

wait_rpc() {  # <pid>
  for i in $(seq 1 120); do
    kill -0 "$1" 2>/dev/null || return 1
    curl -s -m 3 "http://127.0.0.1:$RPC_PORT/get_height" | grep -q '"height"' && return 0
    sleep 1
  done; return 1
}
log_height() { grep -oE "Synced [0-9]+/[0-9]+" "$1" | tail -1 | cut -d' ' -f2 | cut -d/ -f1; }
stop_node() {  # <pid>, one of ours
  curl -s -m 30 "http://127.0.0.1:$RPC_PORT/stop_daemon" -d '{}' > /dev/null
  for i in $(seq 1 30); do kill -0 "$1" 2>/dev/null || { CUR_PID=; return 0; }; sleep 1; done
  kill -TERM "$1" 2>/dev/null
  for i in $(seq 1 600); do kill -0 "$1" 2>/dev/null || { CUR_PID=; return 0; }; sleep 1; done
  echo "SIGKILL $1" >> "$S"; kill -KILL "$1" 2>/dev/null; sleep 3; CUR_PID=
}
sampler() {  # <pid> <rpc_port> <outfile> <interval_s> <logfile>; same columns as G013 sample.sh v2
  local P=$1 PORT=$2 O=$3 I=$4 LG=$5 info h t src s pd hm
  echo "ts,height,target,VmHWM_kB,VmRSS_kB,RssAnon_kB,RssFile_kB,RssShmem_kB,VmSwap_kB,threads,priv_dirty_kB,height_src" > "$O"
  while kill -0 "$P" 2>/dev/null; do
    info=$(curl -s -m 5 "http://127.0.0.1:$PORT/get_info" 2>/dev/null)
    h=$(echo "$info" | grep -o "\"height\": [0-9]*" | head -1 | grep -o "[0-9]*$"); src=rpc
    t=$(echo "$info" | grep -o "\"target_height\": [0-9]*" | grep -o "[0-9]*$")
    if [ -z "$h" ] && [ -n "$LG" ]; then hm=$(grep -oE "Synced [0-9]+/[0-9]+" "$LG" | tail -1 | cut -d" " -f2); h=${hm%/*}; t=${hm#*/}; src=log; fi
    s=$(awk '/^(VmHWM|VmRSS|RssAnon|RssFile|RssShmem|VmSwap|Threads):/{printf "%s,", $2}' "/proc/$P/status" 2>/dev/null)
    pd=$(awk '/^Private_Dirty:/{print $2}' "/proc/$P/smaps_rollup" 2>/dev/null)
    echo "$(date +%s),${h:-},${t:-},${s}${pd:-},$src" >> "$O"
    sleep "$I"
  done
  echo "# process exited $(date)" >> "$O"
}
peer_pid() {  # read-only: PID listening on the PEER port, if visible to us; empty otherwise
  ss -ltnp "sport = :${PEER##*:}" 2>/dev/null | grep -o 'pid=[0-9]*' | head -1 | cut -d= -f2
}
peer_ticks() {  # <pid> -> utime+stime in clock ticks, or empty if unreadable (never signals the process)
  [ -n "$1" ] && sed 's/.*) //' "/proc/$1/stat" 2>/dev/null | awk '{print $12+$13}'
}
TIP=
check_tip() {  # <binary>; sets TIP="<height> <yes|NO>": offline restart on DD, our top header vs the peer's at that height
  TIP="-1 NO"
  port_busy "$RPC_PORT" && { echo "check_tip: rpc port busy, skipped" >> "$S"; return; }
  "$1" --testnet --data-dir "$DD" --offline --non-interactive --no-igd --no-zmq --disable-dns-checkpoints --check-updates disabled --p2p-bind-ip 127.0.0.1 --p2p-bind-port "$P2P_PORT" \
    --rpc-bind-ip 127.0.0.1 --rpc-bind-port "$RPC_PORT" --log-file "$OUT/check.log" --log-level 0 > /dev/null 2>&1 &
  local MP=$!; CUR_PID=$MP; wait_rpc "$MP"
  local r idx ours theirs
  r=$(curl -s -m 30 "http://127.0.0.1:$RPC_PORT/json_rpc" -d '{"jsonrpc":"2.0","id":0,"method":"get_last_block_header"}')
  idx=$(echo "$r" | grep -oE '"height": [0-9]+' | head -1 | grep -oE '[0-9]+$')
  ours=$(echo "$r" | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
  theirs=$(curl -s -m 30 "http://$PEER_RPC/json_rpc" -d "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"get_block_header_by_height\",\"params\":{\"height\":${idx:-0}}}" | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
  stop_node "$MP"
  TIP="$(( ${idx:--1} + 1 )) $([ -n "$ours" ] && [ "$ours" = "$theirs" ] && echo yes || echo NO)"
}

N=${#ARMS[@]}
for r in $(seq 1 "$ROUNDS"); do
  if [ $((r % 2)) -eq 1 ]; then idxs=$(seq 0 $((N - 1))); else idxs=$(seq $((N - 1)) -1 0); fi  # alternate order
  for k in $idxs; do
    IFS='|' read -r L BIN EXTRA <<< "${ARMS[$k]}"
    tag=r${r}_$L
    echo "[$tag] start $(date -Is) loadavg=$(cut -d' ' -f1-3 /proc/loadavg) other_monerod_procs=$(ps -eo comm= | grep -c '^monerod$')" >> "$S"
    check_ports
    prep_dd "$tag"
    LOG=$OUT/$tag.log
    # shellcheck disable=SC2086
    "$BIN" --testnet --data-dir "$DD" --add-exclusive-node "$PEER" --p2p-bind-ip 127.0.0.1 --p2p-bind-port "$P2P_PORT" \
      --rpc-bind-ip 127.0.0.1 --rpc-bind-port "$RPC_PORT" --no-zmq --no-igd --non-interactive \
      --disable-dns-checkpoints --check-updates disabled --log-file "$LOG" --log-level 0 $EXTRA > "$OUT/$tag.stdout" 2>&1 &
    MP=$!; CUR_PID=$MP
    wait_rpc "$MP"
    h0=$(curl -s -m 5 "http://127.0.0.1:$RPC_PORT/get_height" | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$')
    PP=$(peer_pid); pt0=$(peer_ticks "$PP")
    sampler "$MP" "$RPC_PORT" "$OUT/$tag.mem.csv" 2 "$LOG" &
    SP=$!
    t0=$(date +%s); h=0
    while :; do
      h=$(log_height "$LOG"); h=${h:-0}
      [ "$h" -ge "$END" ] && break
      [ $(( $(date +%s) - t0 )) -ge "$TO" ] && break
      kill -0 "$MP" 2>/dev/null || break
      sleep 2
    done
    t1=$(date +%s)
    pt1=$(peer_ticks "$PP")
    if [ -n "$pt0" ] && [ -n "$pt1" ]; then pcpu=$(awk -v a="$pt0" -v b="$pt1" -v hz="$(getconf CLK_TCK)" 'BEGIN{printf "%.1f", (b-a)/hz}'); else pcpu=na; fi
    cpu=$(awk -v hz="$(getconf CLK_TCK)" '{print int(($14+$15)/hz)}' "/proc/$MP/stat" 2>/dev/null)
    io_r=$(awk '/^read_bytes/{print int($2/1048576)}' "/proc/$MP/io" 2>/dev/null); io_w=$(awk '/^write_bytes/{print int($2/1048576)}' "/proc/$MP/io" 2>/dev/null)
    # post-window idle memory: ban the peer on OUR node (local RPC only), let in-flight blocks finish, sample RssAnon, unban
    curl -s -m 30 "http://127.0.0.1:$RPC_PORT/json_rpc" -d "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"set_bans\",\"params\":{\"bans\":[{\"host\":\"$PEER_HOST\",\"ban\":true,\"seconds\":900}]}}" > /dev/null
    sleep "$IDLE_S"
    post=$(awk '/^RssAnon:/{print int($2/1024)}' "/proc/$MP/status" 2>/dev/null)
    curl -s -m 30 "http://127.0.0.1:$RPC_PORT/json_rpc" -d "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"set_bans\",\"params\":{\"bans\":[{\"host\":\"$PEER_HOST\",\"ban\":false}]}}" > /dev/null
    stop_node "$MP"
    wait "$SP" 2>/dev/null
    sleep "$SETTLE_S"
    pa=$(awk -F, 'NR>1 && ($6+0)>m {m=$6+0} END {print int(m/1024)}' "$OUT/$tag.mem.csv")
    pd=$(awk -F, 'NR>1 && ($11+0)>m {m=$11+0} END {print int(m/1024)}' "$OUT/$tag.mem.csv")
    pr=$(awk -F, 'NR>1 && ($5+0)>m {m=$5+0} END {print int(m/1024)}' "$OUT/$tag.mem.csv")
    check_tip "$BIN"; tip=$TIP
    echo "$r,$L,$h0,$h,$(( h - ${h0:-0} )),$(( t1 - t0 )),$pa,$pd,$pr,${io_r:-},${io_w:-},${tip% *},${tip#* },${post:-},${cpu:-},$pcpu" >> "$R"
    echo "[$tag] $EXTRA -> h=$h wall=$((t1 - t0))s peak_anon=${pa}MB post_idle_anon=${post:-?}MB tip=$tip peer_cpu_s=$pcpu (peer pid ${PP:-none})" >> "$S"
  done
done
echo AB_COMPLETE >> "$S"
